const t={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Быстрая проверка только для чтения, готов ли принтер к началу печати."}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"Проверить снова"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"Проверка…"}},ready:{t:0,b:{t:2,i:[{t:3}],s:"Готов к печати"}},notReady:{t:0,b:{t:2,i:[{t:3}],s:"Не готов к печати"}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:"Принтер недоступен"}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Klipper готов"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Klipper не готов (состояние: "},{t:4,k:"state"},{t:3,v:")"}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Печать не выполняется"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Печать уже идёт ("},{t:4,k:"state"},{t:3,v:")"}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Все оси приведены в исходное положение"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Оси не приведены в исходное положение ("},{t:4,k:"axes"},{t:3,v:"); запуск печати обычно сначала выполняет хоминг"}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Справка"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Руководство по проверке перед печатью"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Закрыть"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Что такое проверка перед печатью?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Проверка только для чтения, готов ли принтер к запуску: она ничего не перемещает и не меняет, а лишь сообщает результат. Жёсткие блокировки делают вердикт красным; предупреждения информируют, но не блокируют."}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:"Что проверяется"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Готов ли Klipper (не выключен и не в ошибке), не выполняется ли уже печать, и приведены ли оси в исходное положение (информационно, так как запуск печати обычно сначала выполняет хоминг)."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Глоссарий"}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:"Состояние Klipper"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Собственный статус Klipper: 'ready' (готов) означает, что он подключён и простаивает; 'shutdown' (выключен) или 'error' (ошибка) означает, что он не может печатать, пока состояние не сброшено."}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:"Хоминг"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Перемещение каждой оси к её концевику, чтобы принтер знал положение печатающей головки. Большинство процедур запуска печати выполняют хоминг автоматически."}}}}}}};export{t as default};
